import { path } from '@servicenow/sdk-build-core'
import { createTestContext, findInput, loadTestFile, unzipInputArray } from '../test-utils'
import { XMLParser } from 'fast-xml-parser'

/**
 * Round-Trip Test: daily-data-processing-flow
 *
 * XML Source: sys_hub_flow_258b861aabf84008836e778ed8cec1c0.xml
 * Fluent Source: daily-data-processing-flow.now.ts
 *
 * Flow Name: Daily Data Processing Flow
 * Description: Daily automated data processing with if/else logic and setFlowVariables
 *
 * Features Tested:
 * - Flow definition with scheduled daily trigger
 * - Flow variables (string, integer, datetime, boolean)
 * - setFlowVariables with literals and datapills
 * - If/else conditional logic
 * - Core actions (log, sendEmail)
 * - XML → Fluent → XML round-trip transformation
 */

/**
 * Helper function to validate imports in generated Fluent code
 * @param content - The Fluent code content to validate
 * @param expectedImports - Array of expected import strings
 */
function validateImports(content: string, expectedImports: string[]) {
    expect(content).toContain('import {')
    expectedImports.forEach((importName) => {
        expect(content).toContain(importName)
    })
}

describe('daily-data-processing-flow: Round-Trip Test', () => {
    const ctx = createTestContext({ rootDir: path.resolve(__dirname, '../project') })
    beforeAll(() => ctx.initialize())
    afterEach(() => ctx.cleanup())
    /**
     * Test: daily-data-processing-flow
     * XML: sys_hub_flow_258b861aabf84008836e778ed8cec1c0.xml
     * Type: Flow
     * Features: Scheduled daily trigger, if/else logic, setFlowVariables, core actions
     */
    test('daily-data-processing-flow: Round-trip transformation', async () => {
        const xmlFileName = 'sys_hub_flow_258b861aabf84008836e778ed8cec1c0.xml'
        const project = ctx.createProject()

        // ============================================================================
        // Step 1: XML → Fluent Transformation
        // ============================================================================
        const xmlContent = loadTestFile(xmlFileName, 'example-unit-tests/xml')
        const { changedFiles } = await project.transform({
            path: xmlFileName,
            content: xmlContent,
        })

        expect(changedFiles).toHaveLength(1)
        const fluentContent = changedFiles[0].getContent()
        const fluentFileName = changedFiles[0].getName()

        // Verify imports
        validateImports(fluentContent, [
            'Flow',
            'wfa',
            'trigger',
            'action',
            'StringColumn',
            'BooleanColumn',
            'IntegerColumn',
            'DateTimeColumn',
        ])

        // ===== 1. Flow Definition =====
        expect(fluentContent).toContain('Flow(')
        expect(fluentContent).toContain("name: 'Daily Data Processing Flow'")
        expect(fluentContent).toContain('Daily automated data processing')

        // ===== 2. Flow Variables =====
        // dailyBatchId (order 1)
        expect(fluentContent).toContain('dailyBatchId: StringColumn')
        expect(fluentContent).toContain("label: 'Daily Batch ID'")

        // processedToday (order 2)
        expect(fluentContent).toContain('processedToday: IntegerColumn')
        expect(fluentContent).toContain("label: 'Items Processed Today'")

        // lastProcessingTime (order 3)
        expect(fluentContent).toContain('lastProcessingTime: DateTimeColumn')
        expect(fluentContent).toContain("label: 'Last Processing Time'")

        // isWeekend (order 4)
        expect(fluentContent).toContain('isWeekend: BooleanColumn')
        expect(fluentContent).toContain("label: 'Is Weekend'")

        // currentEnvironment (order 5)
        expect(fluentContent).toContain('currentEnvironment: StringColumn')
        expect(fluentContent).toContain("label: 'Current Environment'")

        // ===== 3. Trigger =====
        expect(fluentContent).toContain('wfa.trigger(')
        expect(fluentContent).toContain('trigger.scheduled.daily')
        expect(fluentContent).toContain("annotation: 'Runs daily at 9:00 AM for automated data processing'")
        expect(fluentContent).toContain('time: Time(')
        expect(fluentContent).toContain('hours: 3')
        expect(fluentContent).toContain('minutes: 30')

        // ===== 4. setFlowVariables: Set daily values =====
        expect(fluentContent).toContain('wfa.flowLogic.setFlowVariables(')
        expect(fluentContent).toContain("annotation: 'Set daily flow variables using inline script logic'")
        expect(fluentContent).toContain('_params.flowVariables')
        expect(fluentContent).toContain("dailyBatchId: 'BATCH_DAILY_001'")
        expect(fluentContent).toContain('processedToday: 0')
        expect(fluentContent).toContain("lastProcessingTime: '2024-01-01 09:00:00'")
        expect(fluentContent).toContain('isWeekend: false')
        expect(fluentContent).toContain("currentEnvironment: 'production'")

        // ===== 5. Action: Log daily start =====
        expect(fluentContent).toContain('wfa.action(')
        expect(fluentContent).toContain('action.core.log')
        expect(fluentContent).toContain("annotation: 'Log daily processing start with assigned values'")
        expect(fluentContent).toContain("log_level: 'info'")
        expect(fluentContent).toContain('log_message: `Daily data processing started')
        expect(fluentContent).toContain("wfa.dataPill(_params.flowVariables.dailyBatchId, 'string')")
        expect(fluentContent).toContain("wfa.dataPill(_params.flowVariables.currentEnvironment, 'string')")
        expect(fluentContent).toContain("wfa.dataPill(_params.flowVariables.isWeekend, 'boolean')")

        // ===== 6. If Logic: Check weekend =====
        expect(fluentContent).toContain('wfa.flowLogic.if(')
        expect(fluentContent).toContain("annotation: 'Check if today is weekend using inline assigned value'")
        expect(fluentContent).toContain("condition: `${wfa.dataPill(_params.flowVariables.isWeekend, 'boolean')}=true`")

        // ===== 7. Weekend Branch =====
        // Action: Weekend processing log
        expect(fluentContent).toContain('wfa.action(')
        expect(fluentContent).toContain('action.core.log')
        expect(fluentContent).toContain("annotation: 'Process data with weekend configuration'")
        expect(fluentContent).toContain("log_level: 'info'")
        expect(fluentContent).toContain('log_message: `Weekend data processing started for batch')
        expect(fluentContent).toContain("wfa.dataPill(_params.flowVariables.dailyBatchId, 'string')")
        expect(fluentContent).toContain('Lower priority (3)')
        expect(fluentContent).toContain('Smaller batch size (50)')

        // setFlowVariables: Update weekend results
        expect(fluentContent).toContain('wfa.flowLogic.setFlowVariables(')
        expect(fluentContent).toContain("annotation: 'Update flow variables with weekend processing results'")
        expect(fluentContent).toContain('_params.flowVariables')
        expect(fluentContent).toContain('processedToday: 150')
        expect(fluentContent).toContain("lastProcessingTime: '2024-01-01 10:00:00'")

        // Action: Weekend summary log
        expect(fluentContent).toContain('wfa.action(')
        expect(fluentContent).toContain('action.core.log')
        expect(fluentContent).toContain("annotation: 'Log weekend processing summary'")
        expect(fluentContent).toContain("log_level: 'info'")
        expect(fluentContent).toContain('log_message: `Weekend processing summary')
        expect(fluentContent).toContain("wfa.dataPill(_params.flowVariables.dailyBatchId, 'string')")
        expect(fluentContent).toContain("wfa.dataPill(_params.flowVariables.processedToday, 'integer')")
        expect(fluentContent).toContain("wfa.dataPill(_params.flowVariables.lastProcessingTime, 'string')")
        expect(fluentContent).toContain("wfa.dataPill(_params.flowVariables.isWeekend, 'boolean')")

        // ===== 8. Else Logic =====
        expect(fluentContent).toContain('wfa.flowLogic.else(')
        expect(fluentContent).toContain("annotation: 'Process data for weekday with higher priority'")

        // ===== 9. Weekday Branch =====
        // Action: Weekday processing log
        expect(fluentContent).toContain('wfa.action(')
        expect(fluentContent).toContain('action.core.log')
        expect(fluentContent).toContain("annotation: 'Process data with weekday configuration'")
        expect(fluentContent).toContain("log_level: 'info'")
        expect(fluentContent).toContain('log_message: `Weekday data processing started for batch')
        expect(fluentContent).toContain("wfa.dataPill(_params.flowVariables.dailyBatchId, 'string')")
        expect(fluentContent).toContain("wfa.dataPill(_params.flowVariables.currentEnvironment, 'string')")
        expect(fluentContent).toContain('High priority (1)')
        expect(fluentContent).toContain('Larger batch size (200)')

        // setFlowVariables: Update weekday results
        expect(fluentContent).toContain('wfa.flowLogic.setFlowVariables(')
        expect(fluentContent).toContain(
            "annotation: 'Update flow variables with weekday processing results and inline calculations'"
        )
        expect(fluentContent).toContain('_params.flowVariables')
        expect(fluentContent).toContain('processedToday: 1550')
        expect(fluentContent).toContain("lastProcessingTime: '2024-01-01 17:00:00'")
        expect(fluentContent).toContain(
            "dailyBatchId: `${wfa.dataPill(_params.flowVariables.dailyBatchId, 'string')}_COMPLETED`"
        )

        // Action: Send email
        expect(fluentContent).toContain('wfa.action(')
        expect(fluentContent).toContain('action.core.sendEmail')
        expect(fluentContent).toContain("annotation: 'Send completion notification with processing summary'")
        expect(fluentContent).toContain('ah_to: wfa.dataPill(_params.flowVariables.dailyBatchId')
        expect(fluentContent).toContain("ah_subject: 'Daily Data Processing Complete - 1234'")
        expect(fluentContent).toContain('ah_body: `')
        expect(fluentContent).toContain('Daily data processing has been completed successfully.')
        expect(fluentContent).toContain('Processing Details:')
        expect(fluentContent).toContain('- Batch ID: 1234')
        expect(fluentContent).toContain('- Environment: production')
        expect(fluentContent).toContain('- Items Processed: 1550')
        expect(fluentContent).toContain('- Processing Time: 2024-01-01 17:00:00')
        expect(fluentContent).toContain('- Weekend Processing: false')
        expect(fluentContent).toContain('- Processing completed at: 2024-01-01 17:00:00')
        expect(fluentContent).toContain('watermark_email: true')

        // ===== 10. Final Action: Log processing summary =====
        expect(fluentContent).toContain('wfa.action(')
        expect(fluentContent).toContain('action.core.log')
        expect(fluentContent).toContain("annotation: 'Log final processing summary with all assigned values'")
        expect(fluentContent).toContain("log_level: 'info'")
        expect(fluentContent).toContain('log_message: `Daily processing summary')
        expect(fluentContent).toContain("wfa.dataPill(_params.flowVariables.dailyBatchId, 'string')")
        expect(fluentContent).toContain("wfa.dataPill(_params.flowVariables.processedToday, 'integer')")
        expect(fluentContent).toContain("wfa.dataPill(_params.flowVariables.lastProcessingTime, 'string')")
        expect(fluentContent).toContain("wfa.dataPill(_params.flowVariables.isWeekend, 'boolean')")

        // ============================================================================
        // Step 2: Fluent → XML Transformation
        // ============================================================================
        const tempProject = ctx.createProject()
        tempProject.addFile({ path: fluentFileName, content: fluentContent })

        const output = await tempProject.getFile(fluentFileName)!.getOutput()
        expect(output.length).toBeGreaterThan(0)

        // ============================================================================
        // Step 3: Parse and Validate Regenerated XML
        // ============================================================================
        const parser = new XMLParser({ ignoreAttributes: false })
        const mergedRecords: Record<string, any[]> = {}

        for (const file of output) {
            const parsed = parser.parse(file.content)['record_update']
            Object.entries(parsed).forEach(([table, value]) => {
                if (!mergedRecords[table]) {
                    mergedRecords[table] = []
                }
                if (Array.isArray(value)) {
                    mergedRecords[table].push(...value)
                } else if (value && typeof value === 'object') {
                    mergedRecords[table].push(value)
                }
            })
        }

        // Verify required record types exist
        expect(mergedRecords['sys_hub_flow']).toBeDefined()
        expect(mergedRecords['sys_hub_trigger_instance_v2']).toBeDefined()
        expect(mergedRecords['sys_hub_flow_variable']).toBeDefined()
        expect(mergedRecords['sys_hub_flow_logic_instance_v2']).toBeDefined()
        expect(mergedRecords['sys_hub_action_instance_v2']).toBeDefined()

        // ============================================================================
        // Step 4: Validate Flow Record
        // ============================================================================
        const flows = mergedRecords['sys_hub_flow']
        expect(flows.length).toBeGreaterThanOrEqual(1)
        const flow = flows.find((f: any) => f.name === 'Daily Data Processing Flow')
        expect(flow).toBeDefined()
        expect(flow.description).toContain('Daily automated data processing')
        expect(flow.type).toBe('flow')
        expect(flow.generation_source).toBe('fluent')
        expect(flow.run_as).toBe('system')

        // ============================================================================
        // Step 5: Validate Trigger (Scheduled Daily)
        // ============================================================================
        const triggerInstances = mergedRecords['sys_hub_trigger_instance_v2']
        expect(triggerInstances.length).toBeGreaterThan(0)

        // Find the trigger that belongs to this flow
        const trigger = triggerInstances.find((t: any) => t.flow === flow.sys_id)
        expect(trigger).toBeDefined()
        expect(trigger.trigger_type).toBe('daily')

        // Validate trigger inputs (encrypted) - contains time configuration
        expect(trigger.trigger_inputs).toBeDefined()
        const triggerInputs = unzipInputArray(trigger.trigger_inputs) as any
        expect(triggerInputs).toBeDefined()

        // ============================================================================
        // Step 6: Validate Flow Variables
        // ============================================================================
        const flowVars = mergedRecords['sys_hub_flow_variable']
        expect(flowVars.length).toBeGreaterThanOrEqual(5)

        const dailyBatchId = flowVars.find((v: any) => v.element === 'dailyBatchId')
        expect(dailyBatchId).toBeDefined()
        expect(dailyBatchId.label).toBe('Daily Batch ID')
        expect(dailyBatchId.internal_type).toBe('string')

        const processedToday = flowVars.find((v: any) => v.element === 'processedToday')
        expect(processedToday).toBeDefined()
        expect(processedToday.label).toBe('Items Processed Today')
        expect(processedToday.internal_type).toBe('integer')

        const isWeekend = flowVars.find((v: any) => v.element === 'isWeekend')
        expect(isWeekend).toBeDefined()
        expect(isWeekend.label).toBe('Is Weekend')
        expect(isWeekend.internal_type).toBe('boolean')

        const lastProcessingTime = flowVars.find((v: any) => v.element === 'lastProcessingTime')
        expect(lastProcessingTime).toBeDefined()
        expect(lastProcessingTime.label).toBe('Last Processing Time')
        expect(lastProcessingTime.internal_type).toBe('glide_date_time')

        const currentEnvironment = flowVars.find((v: any) => v.element === 'currentEnvironment')
        expect(currentEnvironment).toBeDefined()
        expect(currentEnvironment.label).toBe('Current Environment')
        expect(currentEnvironment.internal_type).toBe('string')

        // ============================================================================
        // Step 7: Validate Flow Logic Data Values (Decompress and Verify)
        // ============================================================================
        const flowLogicInstances = mergedRecords['sys_hub_flow_logic_instance_v2']
        expect(flowLogicInstances.length).toBeGreaterThanOrEqual(3) // At least 3 setFlowVariables

        // Initial setFlowVariables with literals
        const setDailyValues = flowLogicInstances.find(
            (fl: any) => fl.comment === 'Set daily flow variables using inline script logic'
        )
        expect(setDailyValues).toBeDefined()
        const dailyValues = unzipInputArray(setDailyValues.values) as any
        const dailyVar = (name: string) => dailyValues.variables.find((v: any) => v.name === name)?.value
        expect(dailyVar('dailyBatchId')).toBe('BATCH_DAILY_001')
        expect(dailyVar('processedToday')).toBe('0')
        expect(dailyVar('isWeekend')).toBe('false')
        expect(dailyVar('currentEnvironment')).toBe('production')

        // Weekend setFlowVariables
        const updateWeekendResults = flowLogicInstances.find(
            (fl: any) => fl.comment === 'Update flow variables with weekend processing results'
        )
        expect(updateWeekendResults).toBeDefined()
        const weekendValues = unzipInputArray(updateWeekendResults.values) as any
        const weekendVar = (name: string) => weekendValues.variables.find((v: any) => v.name === name)?.value
        expect(weekendVar('processedToday')).toBe('150')

        // Weekday setFlowVariables with datapill
        const updateWeekdayResults = flowLogicInstances.find(
            (fl: any) => fl.comment === 'Update flow variables with weekday processing results and inline calculations'
        )
        expect(updateWeekdayResults).toBeDefined()
        const weekdayValues = unzipInputArray(updateWeekdayResults.values) as any
        const weekdayVar = (name: string) => weekdayValues.variables.find((v: any) => v.name === name)?.value
        expect(weekdayVar('processedToday')).toBe('1550')
        // dailyBatchId has a datapill template
        expect(weekdayVar('dailyBatchId')).toContain('dailyBatchId')
        expect(weekdayVar('dailyBatchId')).toContain('_COMPLETED')

        // ============================================================================
        // Step 8: Validate Actions
        // ============================================================================
        const actionInstances = mergedRecords['sys_hub_action_instance_v2']
        expect(actionInstances.length).toBeGreaterThanOrEqual(6) // Multiple log actions + sendEmail

        // Initial log action with dataPills
        const logDailyStart = actionInstances.find((a: any) => a.comment?.includes('Log daily processing start'))
        expect(logDailyStart).toBeDefined()
        const logStartValues = unzipInputArray(logDailyStart.values) as any
        const logStartVar = (name: string) => findInput(logStartValues, name)?.value
        expect(logStartVar('log_level')).toBe('info')
        expect(logStartVar('log_message')).toContain('Daily data processing started')
        expect(logStartVar('log_message')).toContain('dailyBatchId')
        expect(logStartVar('log_message')).toContain('currentEnvironment')
        expect(logStartVar('log_message')).toContain('isWeekend')

        // Weekend log action
        const weekendLog = actionInstances.find((a: any) =>
            a.comment?.includes('Process data with weekend configuration')
        )
        expect(weekendLog).toBeDefined()
        const weekendLogValues = unzipInputArray(weekendLog.values) as any
        const weekendLogVar = (name: string) => findInput(weekendLogValues, name)?.value
        expect(weekendLogVar('log_level')).toBe('info')
        expect(weekendLogVar('log_message')).toContain('Weekend data processing started')

        // Weekend summary log
        const weekendSummary = actionInstances.find((a: any) => a.comment?.includes('Log weekend processing summary'))
        expect(weekendSummary).toBeDefined()
        const weekendSummaryValues = unzipInputArray(weekendSummary.values) as any
        const weekendSummaryVar = (name: string) => findInput(weekendSummaryValues, name)?.value
        expect(weekendSummaryVar('log_message')).toContain('Weekend processing summary')

        // Weekday log action
        const weekdayLog = actionInstances.find((a: any) =>
            a.comment?.includes('Process data with weekday configuration')
        )
        expect(weekdayLog).toBeDefined()
        const weekdayLogValues = unzipInputArray(weekdayLog.values) as any
        const weekdayLogVar = (name: string) => findInput(weekdayLogValues, name)?.value
        expect(weekdayLogVar('log_level')).toBe('info')
        expect(weekdayLogVar('log_message')).toContain('Weekday data processing started')

        // SendEmail action
        const sendEmailAction = actionInstances.find((a: any) => a.comment?.includes('Send completion notification'))
        expect(sendEmailAction).toBeDefined()
        const emailValues = unzipInputArray(sendEmailAction.values) as any
        const emailVar = (name: string) => findInput(emailValues, name)?.value
        expect(emailVar('ah_subject')).toContain('Daily Data Processing Complete')
        expect(emailVar('ah_body')).toContain('Daily data processing has been completed')
        expect(emailVar('ah_body')).toContain('Processing Details')
        expect(emailVar('watermark_email')).toBe(true)

        // Final log action with all dataPills
        const finalLog = actionInstances.find((a: any) => a.comment?.includes('Log final processing summary'))
        expect(finalLog).toBeDefined()
        const finalLogValues = unzipInputArray(finalLog.values) as any
        const finalLogVar = (name: string) => findInput(finalLogValues, name)?.value
        expect(finalLogVar('log_level')).toBe('info')
        expect(finalLogVar('log_message')).toContain('Daily processing summary')
        expect(finalLogVar('log_message')).toContain('dailyBatchId')
        expect(finalLogVar('log_message')).toContain('processedToday')
        expect(finalLogVar('log_message')).toContain('lastProcessingTime')
        expect(finalLogVar('log_message')).toContain('isWeekend')
    })
})
